#!/usr/bin/env python3
"""Embed the reviewable browser sources; --check detects stale generated bytes."""
import gzip
import io
import sys
from pathlib import Path
root = Path(__file__).resolve().parents[1]
html = (root / 'web/index.html').read_text(encoding='utf-8').replace('/*POSE_SCRIPT*/', (root / 'web/pose_comparison.js').read_text(encoding='utf-8')).replace('/*WHEEL_WORK_SCRIPT*/', (root / 'web/wheel_work.js').read_text(encoding='utf-8')).replace('/*RUNTIME_SCRIPT*/', (root / 'web/runtime.js').read_text(encoding='utf-8'))
compressed = io.BytesIO()
# No timestamp, host OS or filename in the generated representation.
with gzip.GzipFile(fileobj=compressed, filename='', mode='wb', compresslevel=9, mtime=0) as archive:
    archive.write(html.encode('utf-8'))
payload = compressed.getvalue()
gzip_literals = '\n'.join(
    '"' + ''.join(f'\\x{byte:02x}' for byte in payload[i:i + 32]) + '"'
    for i in range(0, len(payload), 32)
)
output = ('#pragma once\n#include <Arduino.h>\nstatic const char RUNTIME_HTML[] PROGMEM = R"FREEFOOT('
          + html + ')FREEFOOT";\nstatic const char RUNTIME_HTML_GZIP[] PROGMEM =\n' + gzip_literals + ';\n')
path = root / 'src/runtime_web.h'
if '--check' in sys.argv:
    assert path.read_text(encoding='utf-8') == output, 'Run python tools/embed_runtime_web.py'
else:
    with path.open('w', encoding='utf-8', newline='\n') as generated:
        generated.write(output)
